 return `<div class="in-report-title"><div><p class="in-overline">${say(l,'YOUR PERSONAL REFLECTION','आपकी व्यक्तिगत झलक')}</p><h3>${say(l,'A picture of your responses.','आपके जवाब, एक नज़र में।')}</h3></div><span class="in-six-badge"><b>6</b>${say(l,'areas','पहलू')}</span></div><div class="in-sample-bars">${areas.map((a,j)=>`<div><span>${a[i]}</span><div role="img" aria-label="${esc(`${a[i]}: ${sampleCounts[j].map((n,k)=>`${labels[k]} ${n}`).join(', ')}`)}">${sampleCounts[j].map((n,k)=>`<i class="in-tone-${k}" style="flex:${n}" title="${esc(labels[k])}: ${n}"></i>`).join('')}</div><small>6</small></div>`).join('')}</div><div class="in-report-key">${labels.map((label,j)=>`<span><i class="in-tone-${j}"></i>${esc(label)}</span>`).join('')}</div><p class="in-fine">${say(l,'Illustrative responses · 6 questions per area. Colours show answer frequency, not better or worse mental health.','उदाहरण के जवाब · हर विषय में 6 सवाल। रंग जवाबों की frequency बताते हैं, बेहतर या खराब मानसिक स्वास्थ्य नहीं।')}</p>`;
